p.add_argument('--allow-disposable-reset',action='store_true');a=p.parse_args();assert a.allow_disposable_reset
root=pathlib.Path(__file__).resolve().parents[2];out=pathlib.Path(a.output).resolve();out.parent.mkdir(parents=True,exist_ok=True);prior=out.with_name(out.stem+'-phase62.json')
baseline=subprocess.run([sys.executable,str(root/'scripts/testing/phase62_postgres.py'),'--bin-dir',a.bin_dir,'--socket',a.socket,'--original-functions',a.original_functions,'--output',str(prior),'--allow-disposable-reset'],cwd=root);assert baseline.returncode==0
base=[str(pathlib.Path(a.bin_dir)/'psql'),'-X','-h',a.socket,'-U','postgres','-v','ON_ERROR_STOP=1','-d','busy_phase58_disposable'];results=[]
B='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';O='cccccccc-cccc-4ccc-8ccc-cccccccccccc';M='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee';D='dddddddd-dddd-4ddd-8ddd-dddddddddddd';B2='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'
def call(sql):return subprocess.run(base,input=sql,text=True,capture_output=True,timeout=15)
def stage(name,sql):
 r=call(sql);results.append({'id':name,'passed':r.returncode==0,'exitCode':r.returncode,'output':r.stdout+r.stderr});return r.returncode==0

def auth(sql,uid=O,role='authenticated',commit=False):return f"BEGIN; SET LOCAL ROLE {role}; SET LOCAL request.jwt.claim.sub='{uid}';\n{sql}\n"+('COMMIT;' if commit else 'ROLLBACK;')
def reject(sql,code='42501'):return f"DO $t$ BEGIN BEGIN {sql}; RAISE EXCEPTION 'Expected denial missing'; EXCEPTION WHEN SQLSTATE '{code}' THEN NULL; END; END $t$;"
def discover(b=B,after='NULL'):return f"public.busy_owner_reply_discover_v1('{b}',{after})"
try:
 assert str((pathlib.Path(a.socket).parent/'data').resolve()) in call('SHOW data_directory;').stdout
 stage('restore-synthetic-owner',f"INSERT INTO public.busy_business_memberships(business_id,user_id,role) VALUES('{B}','{O}','owner');")
 if not stage('discovery-candidate-load',(root/'docs/sql-proposals/phase63-snapshot/discovery.sql').read_text()):raise RuntimeError('Discovery SQL failed')
 stage('owner-discovery-fixed-recognition-metadata',auth(f"DO $t$ DECLARE v jsonb; BEGIN v:={discover()}; IF v->>'revision'<>'5' OR jsonb_array_length(v->'items')<>1 OR (v->'items'->0)-ARRAY['customerId','enquiryId','customerName']<>'{{}}'::jsonb OR v::text LIKE '%sourceStamp%' OR v::text LIKE '%Concurrent committed%' OR v::text LIKE '%futureExtension%' THEN RAISE EXCEPTION 'Discovery disclosure: %',v; END IF; END $t$;"))
 for uid,label in [(M,'member'),(D,'foreign-owner'),('','unauthenticated')]:stage(label+'-discovery-denied',auth(reject('PERFORM '+discover()),uid=uid))
 stage('admin-private-discovery-denied',f"BEGIN; UPDATE public.busy_business_memberships SET role='admin' WHERE business_id='{B}' AND user_id='{O}'; SET LOCAL ROLE authenticated; SET LOCAL request.jwt.claim.sub='{O}'; {reject('PERFORM '+discover())} ROLLBACK;")
 stage('service-private-discovery-denied',auth(reject('PERFORM '+discover()),role='service_role'))
 for name,expr in [('duplicate-customer',"jsonb_set(payload,'{customers}',(payload->'customers')||(payload->'customers'))"),('duplicate-enquiry',"jsonb_set(payload,'{inboxItems}',(payload->'inboxItems')||(payload->'inboxItems'))"),('unsupported-private-version',"jsonb_set(payload,'{customers,0,privateEnquiryReply,version}','3')"),('other-owner-private-reply',f"jsonb_set(payload,'{{customers,0,privateEnquiryReply,ownerId}}','\"{D}\"')"),('foreign-customer',f"jsonb_set(payload,'{{customers,0,businessId}}','\"{B2}\"')"),('changed-source',"jsonb_set(payload,'{inboxItems,0,rawText}','\"Changed request\"')")]:
  stage(name+'-not-discovered',f"BEGIN; UPDATE public.busy_business_snapshots SET payload={expr} WHERE business_id='{B}'; SET LOCAL ROLE authenticated; SET LOCAL request.jwt.claim.sub='{O}'; DO $t$ BEGIN IF {discover()}->'items'<>'[]'::jsonb THEN RAISE EXCEPTION 'Invalid record discovered'; END IF; END $t$; ROLLBACK;")
 stage('malformed-collection-denied',f"BEGIN; UPDATE public.busy_business_snapshots SET payload=jsonb_set(payload,'{{customers}}','{{}}') WHERE business_id='{B}'; SET LOCAL ROLE authenticated; SET LOCAL request.jwt.claim.sub='{O}'; {reject('PERFORM '+discover(),'22023')} ROLLBACK;")
 stage('same-ids-second-business-fixture',f"BEGIN; SET LOCAL request.jwt.claim.sub='{D}'; INSERT INTO public.busy_business_snapshots(business_id) VALUES('{B2}'); UPDATE public.busy_business_snapshots SET payload=(SELECT jsonb_set(jsonb_set(jsonb_set(payload,'{{customers,0,privateEnquiryReply,ownerId}}','\"{D}\"'),'{{customers,0,privateEnquiryReply,businessId}}','\"{B2}\"'),'{{customers,0,privateEnquiryReply,reference,businessId}}','\"{B2}\"') FROM public.busy_business_snapshots WHERE business_id='{B}') WHERE business_id='{B2}'; COMMIT;")
 stage('second-owner-sees-only-own-same-ids',auth(f"DO $t$ DECLARE v jsonb; BEGIN v:={discover(B2)}; IF v->>'businessId'<>'{B2}' OR v->'items'->0->>'customerId'<>'alex' THEN RAISE EXCEPTION 'Wrong tenant discovery'; END IF; END $t$;",uid=D))
 stage('same-ids-do-not-cross-business',auth(reject('PERFORM '+discover(B2))))
 stage('empty-business-no-invented-records',f"BEGIN; UPDATE public.busy_business_snapshots SET payload='{{}}' WHERE business_id='{B2}'; SET LOCAL ROLE authenticated; SET LOCAL request.jwt.claim.sub='{D}'; DO $t$ BEGIN IF {discover(B2)}->'items'<>'[]'::jsonb THEN RAISE EXCEPTION 'Invented discovery'; END IF; END $t$; ROLLBACK;")
 # Clone only synthetic source fixtures to test fixed 25-entry paging.
 stage('bounded-page-stable-identity',f"BEGIN; DO $t$ DECLARE p jsonb; c jsonb; e jsonb; rows jsonb:='[]'; items jsonb:='[]'; id text; i int; v jsonb; BEGIN SELECT payload INTO p FROM public.busy_business_snapshots WHERE business_id='{B}'; FOR i IN 1..26 LOOP id:='c'||lpad(i::text,2,'0'); c:=(p->'customers'->0)-'privateEnquiryReply'; c:=jsonb_set(c,'{{id}}',to_jsonb(id)); e:=jsonb_set(jsonb_set(p->'inboxItems'->0,'{{id}}',to_jsonb('e'||id)),'{{filedCustomerId}}',to_jsonb(id)); c:=c||jsonb_build_object('privateEnquiryReply',(p->'customers'->0->'privateEnquiryReply')||jsonb_build_object('customerId',id,'sourceStamp',jsonb_build_array(c,e)::text,'reference',(p->'customers'->0->'privateEnquiryReply'->'reference')||jsonb_build_object('customerId',id,'inboxId','e'||id)));rows:=rows||jsonb_build_array(c);items:=items||jsonb_build_array(e);END LOOP;UPDATE public.busy_business_snapshots SET payload=jsonb_set(jsonb_set(p,'{{customers}}',rows),'{{inboxItems}}',items) WHERE business_id='{B}';END $t$;SET LOCAL ROLE authenticated;SET LOCAL request.jwt.claim.sub='{O}';DO $t$ DECLARE v jsonb; w jsonb; BEGIN v:={discover()};w:=public.busy_owner_reply_discover_v1('{B}',v->>'nextAfter');IF jsonb_array_length(v->'items')<>25 OR v->>'hasMore'<>'true' OR jsonb_array_length(w->'items')<>1 OR w->>'hasMore'<>'false' OR w->'items'->0->>'customerId'<>'c26' THEN RAISE EXCEPTION 'Paging identity failed'; END IF;END $t$;ROLLBACK;")
 stage('concurrent-version-change-invalidates-old-review',auth(f"DO $t$ DECLARE v jsonb; r jsonb; BEGIN v:=public.busy_owner_reply_review_v1('{B}','alex','enquiry',5);r:=public.busy_owner_reply_text_v2('{B}','alex','enquiry',5,v->>'recordHash',v->>'sourceHash','New account wording');IF r->>'revision'<>'6' THEN RAISE EXCEPTION 'Bad receipt';END IF;END $t$;",commit=True))
 stage('stale-discovery-is-not-opening-authority',auth(reject(f"PERFORM public.busy_owner_reply_review_v1('{B}','alex','enquiry',5)",'40001')))
 stage('fresh-discovery-observes-new-revision',auth(f"DO $t$ BEGIN IF {discover()}->>'revision'<>'6' THEN RAISE EXCEPTION 'Stale observation';END IF;END $t$;"))
 stage('explicit-removal-no-discovery-resurrection',f"BEGIN;SET LOCAL request.jwt.claim.sub='{O}';DO $t$ DECLARE r jsonb; BEGIN SELECT payload->'customers'->0->'privateEnquiryReply' INTO r FROM public.busy_business_snapshots WHERE business_id='{B}';PERFORM public.busy_snapshot_private_mutation_v1('{B}',6,1,'private_reply_remove','alex',r);END $t$;SET LOCAL ROLE authenticated;DO $t$ BEGIN IF {discover()}->'items'<>'[]'::jsonb THEN RAISE EXCEPTION 'Deleted draft resurrected';END IF;END $t$;ROLLBACK;")
 stage('no-unreviewed-initial-filing-endpoint',auth(reject(f"PERFORM public.busy_owner_initial_filing_v1('{B}')",'42883')))
 stage('raw-read-still-denied',auth(reject('PERFORM payload FROM public.busy_business_snapshots')))
 holder=subprocess.Popen(base+['-q'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1);holder.stdin.write(f"BEGIN;DELETE FROM public.busy_business_memberships WHERE business_id='{B}' AND user_id='{O}';\n\\echo PHASE63_LOCKED\n");holder.stdin.flush();assert any('PHASE63_LOCKED' in l for l in holder.stdout)
 contender=subprocess.Popen(base,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);contender.stdin.write("SET statement_timeout='5s';\n"+auth('SELECT '+discover()+';'));contender.stdin.close();time.sleep(.2);blocked=contender.poll() is None;holder.stdin.write('COMMIT;\n\\q\n');holder.stdin.flush();holder.stdin.close();holder.wait(timeout=8);contender.wait(timeout=8);output=contender.stdout.read()+contender.stderr.read();results.append({'id':'discovery-waits-for-revocation','passed':blocked and holder.returncode==0 and contender.returncode!=0 and 'Not authorised' in output,'exitCode':contender.returncode,'holderExitCode':holder.returncode,'expectedDenial':True,'output':output})
 stage('discovery-readonly-rollback',(root/'docs/sql-proposals/phase63-snapshot/rollback-readonly.sql').read_text())
 stage('rollback-discovery-denied',auth(reject('PERFORM '+discover())))
 stage('rollback-raw-data-still-private',auth(reject('PERFORM payload FROM public.busy_business_snapshots')))
except Exception as e:results.append({'id':'runner','passed':False,'error':str(e)})
finally:
 rows=json.loads(prior.read_text())['results']+results;data={'scope':'Local synthetic PostgreSQL17, mock UID, not JWT/PostgREST','baselineExitCode':baseline.returncode,'results':rows,'summary':{'passed':sum(x['passed'] for x in rows),'failed':sum(not x['passed'] for x in rows),'blocked':0,'unexecuted':0},'hostedQueries':0};out.write_text(json.dumps(data,indent=2)+'\n');print(json.dumps(data['summary']));sys.exit(0 if not data['summary']['failed'] else 1)
